mapper.sql:
where a.tenant_id = #{c.tenantId}
  and a.business_type = #{c.businessType}
  and a.business_key in

      #{businessKey}


    and a.id not in

        #{deniedApplyId}



    and t.TASK_DEF_KEY_ in

        #{taskDefinitionKey}



    and (
        t.ASSIGNEE_ in

            #{assigneeIdentifier}


            or exists (
                select 1 from identity_user iu
                where iu.id in

                    #{assigneeId}

                and iu.username = t.ASSIGNEE_
            )

    )


    and (

        or (t.END_TIME_ is null and t.DELETE_REASON_ is null)
        or (t.END_TIME_ is not null and t.DELETE_REASON_ is null)
        or t.DELETE_REASON_ is not null

    )



        and t.ASSIGNEE_ is not null
        and t.ASSIGNEE_ is null



    and a.apply_status in

        #{applyStatus}





            and exists (
                select 1 from workflow_task_record r
                where r.tenant_id = a.tenant_id
                  and r.process_instance_id = a.process_instance_id
                  and r.action = 'RETURN'
            )


            and not exists (
                select 1 from workflow_task_record r
                where r.tenant_id = a.tenant_id
                  and r.process_instance_id = a.process_instance_id
                  and r.action = 'RETURN'
            )




    and t.START_TIME_ >= #{c.createTimeBegin}


    and t.START_TIME_ <= #{c.createTimeEnd}


    and t.END_TIME_ >= #{c.endTimeBegin}


    and t.END_TIME_ <= #{c.endTimeEnd}


    and (t.NAME_ like #{c.keyword} or t.TASK_DEF_KEY_ like #{c.keyword})


    and (
        t.ASSIGNEE_ in

            #{selfIdentifier}

        or exists (
            select 1 from ACT_HI_IDENTITYLINK il
            where il.TASK_ID_ = t.ID_
              and il.TYPE_ = 'candidate'
              and (
                  il.USER_ID_ in

                      #{selfIdentifier}


                      or il.GROUP_ID_ in

                          #{selfGroup}


              )
        )
    )

mapper.select:
select links.TASK_ID_ as taskId, links.USER_ID_ as userId, links.GROUP_ID_ as groupId from ( select TASK_ID_, USER_ID_, GROUP_ID_ from ACT_HI_IDENTITYLINK where TYPE_ = 'candidate' and TASK_ID_ in
#{taskId}
union select TASK_ID_, USER_ID_, GROUP_ID_ from ACT_RU_IDENTITYLINK where TYPE_ = 'candidate' and TASK_ID_ in
#{taskId}
) links
